// SelfLearn · Curso 01 · Nederlands A0 → B2, hecho para Renzo (hispanohablante, vive en Brabante,
// control de inventario en un almacén con turnos de mañana y tarde, gimnasio, camino hacia análisis de datos y NT2).
// Ruta MCER orientativa: ninguna actividad certifica un nivel oficial. Sin datos reales de empleadores ni clientes.
// Los IDs de las 33 unidades anteriores se conservan para no perder el progreso histórico.
// Formato compacto: palabras y frases "neerlandés|español"; diálogo "Quién: neerlandés|español".
const U = (id, level, topic, title, goal, words, sentences, grammar, dialogue = []) => ({
  id, level, topic, title, goal,
  words: words.map(w => w.split("|")),
  sentences: sentences.map(s => s.split("|")),
  grammar: { title: grammar[0], text: grammar[1] },
  dialogue: dialogue.map(line => { const i = line.indexOf(": "), [nl, es] = line.slice(i + 2).split("|"); return { who: line.slice(0, i), t: nl, es }; })
});

